    class Emitter {
        constructor() {
            this.events = new Map();
        }
        on(event, handler) {
            let set = this.events.get(event);
            if (!set) {
                set = new Set();
                this.events.set(event, set);
            }
            set.add(handler);
            return () => this.off(event, handler);
        }
        off(event, handler) {
            const set = this.events.get(event);
            if (!set)
                return;
            set.delete(handler);
            if (set.size === 0) {
                this.events.delete(event);
            }
        }
        emit(event, ...args) {
            const set = this.events.get(event);
            if (!set)
                return;
            for (const fn of [...set]) {
                fn(...args);
            }
        }
        once(event, handler) {
            const wrap = (...args) => {
                handler(...args);
                this.off(event, wrap);
            };
            return this.on(event, wrap);
        }
        clear(event) {
            if (event) {
                this.events.delete(event);
            }
            else {
                this.events.clear();
            }
        }
        useEvent(event, getter) {
            const { useState, useEffect } = getHtmPreact();
            const [state, setState] = useState(getter || (() => null));
            useEffect(() => {
                const off = this.on(event, (...args) => {
                    if (getter) {
                        const next = getter?.(...args);
                        setState(next);
                    }
                    else {
                        setState(args[0]);
                    }
                });
                return () => off();
            }, []);
            return state;
        }
    }
