                profileName: profile.profileName || "",
                tabKey: profile.tabKey || "post",
                status: "idle",
                createdAt: Date.now(),
                updatedAt: Date.now(),
                lastRunAt: 0,
                completedAt: 0,
                knownIds: [],
                downloadedIds: [],
