            const total = Number(response.headers.get("content-length") || 0);
            const chunks = [];
            let loaded = 0;
            if (!reader) {
                const blob = await response.blob();
                progress.emit({ loaded: blob.size, total: blob.size }, true);
                return { blob, loaded: blob.size, total: blob.size };
            }
            while (true) {
                if (signal?.aborted)
                    throw new DOMException("已取消", "AbortError");
                const { done, value } = await this._readChunkWithWatch(reader, progress, signal, loaded, total);
                if (done)
                    break;
                chunks.push(value);
                loaded += value.byteLength;
                progress.emit({ loaded, total, hasTransferData: true });
            }
            return {
                blob: new Blob(chunks, {
                    type: response.headers.get("content-type") ||
                        "application/octet-stream",
                }),
                loaded,
                total,
            };
