            if (!media)
                return '无标题作品';
            const awemeId = MediaAssets.id(media), title = MediaAssets.title(media);
            const now = new Date(), created = new Date(Number(media.createTime || 0) * 1000);
            const context = { media, desc: title, nickname: media.authorInfo?.nickname || '未知作者', short_id: MediaHandler.toShortId(awemeId), aweme_id: awemeId,
                tags: (media.textExtra || []).map(x => x.hashtagName).filter(Boolean).join('_'), author_info: media.authorInfo || {}, uid: media.authorInfo?.uid || media.authorUserId || '',
                music_name: media.music?.musicName || media.music?.title || '', now_date: now, create_date: created,
                now_YYYYMMDD: formatDate(now, 'YYYYMMDD'), now_YYYYMMDD_HHmmss: formatDate(now, 'YYYYMMDD_HHmmss'),
                create_date_YYYYMMDD: formatDate(created, 'YYYYMMDD'), create_date_YYYYMMDD_HHmmss: formatDate(created, 'YYYYMMDD_HHmmss') };
