            this.q('#singleLaunchHint').textContent = album ? '选择一张图片或一个动态子项' : '单独保存视频、封面或原声';
            this.q('#workTitle').textContent = media?.desc || (media ? '无标题作品' : '暂未读取到当前作品');
            this.q('#workMeta').textContent = media ? `${media.authorInfo?.nickname || '未知作者'} · ${album ? media.images.length + ' 项图集' : '视频'}` : '正在自动识别当前作品，请稍候。';
            const tags = [...new Set((media?.textExtra || []).map(x => String(x.hashtagName || '').trim()).filter(Boolean))];
